"""Generic wrapper for discovered/generated configuration files."""

from pathlib import Path
from typing import Any, Generic, TypeVar, cast

from pydantic import BaseModel

T = TypeVar("T", bound=BaseModel)


class DiscoveredConfig(BaseModel, Generic[T]):
    """A config loaded from disk or generated by recommend, carrying its source filename.

    Attributes:
        config: The parsed Pydantic model instance.
        filename: Basename of the TOML file (e.g. "reconstruct-meso.toml").
    """

    config: T
    filename: str

    def write_to(self, directory: Path) -> Path:
        """Write the config to directory/self.filename. Returns the output path."""
        path = directory / self.filename
        if hasattr(self.config, "to_toml"):
            cast(Any, self.config).to_toml(path)
        else:
            import tomli_w  # noqa: PLC0415

            with open(path, "wb") as f:
                tomli_w.dump(self.config.model_dump(exclude_none=True), f)
        return path
